import * as React from "react"

function Comp3dCard2({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="3d-card-2"
      className={className}
      {...props}
    >
      <style>{".flip-card {\n      perspective: 1000px;\n    }\n\n    .flip-inner {\n      transition: transform 0.8s;\n      transform-style: preserve-3d;\n    }\n\n    .flipped {\n      transform: rotateY(180deg);\n    }\n\n    .flip-front, .flip-back {\n      backface-visibility: hidden;\n      -webkit-backface-visibility: hidden;\n    }\n\n    .flip-back {\n      transform: rotateY(180deg);\n    }"}</style>
      <div className="flip-card w-80 h-48">
          <div className="flip-inner relative w-full h-full">

            <div className="flip-front absolute w-full h-full bg-white text-black flex items-center justify-center rounded-xl shadow-xl text-xl font-bold">
              Click Me (Front)
            </div>

            <div className="flip-back absolute w-full h-full bg-indigo-600 text-white flex items-center justify-center rounded-xl shadow-xl text-xl font-bold">
              Hello! (Back)
            </div>
          </div>
        </div>
    </div>
  )
}

export { Comp3dCard2 }
